const input = $input.first().json;

if (input.attachment) {
  const { name, mime, base64 } = input.attachment;
  if (!['image/jpeg', 'image/png', 'application/pdf'].includes(mime) ||
      typeof name !== 'string' || !name || name.length > 255 ||
      typeof base64 !== 'string' || !base64 || base64.length > 6990508 ||
      base64.length % 4 !== 0 || /[^A-Za-z0-9+/=]/.test(base64)) {
    throw new Error('Geçersiz dosya eki.');
  }
  return [{ json: {
    question: typeof input.question === 'string' ? input.question.slice(0, 8000) : '',
    model: typeof input.openaiModel === 'string' && input.openaiModel.trim() ? input.openaiModel.trim() : 'gpt-5-mini',
    attachment: { name, mime, base64 },
  } }];
}

const question =
  typeof input.question === 'string'
    ? input.question.trim()
    : '';

const model =
  typeof input.openaiModel === 'string' && input.openaiModel.trim()
    ? input.openaiModel.trim()
    : typeof input.model === 'string' && input.model.trim()
      ? input.model.trim()
      : '';

const role =
  typeof input.role === 'string'
    ? input.role.trim()
    : '';

const task =
  typeof input.task === 'string'
    ? input.task.trim()
    : '';

if (/^(?:eylem|aksiyon|uygulama) planlama uzmanı$|^(?:action|implementation) planning (?:expert|specialist)$/iu.test(role) || /(?:her(?:\s+bir)?|diğer|önceki|tüm|bütün|başka\s+bir|öteki)\s+(?:(?:bağımsız|görevli)\s+)?(?:uzman|ajan|agent)\p{L}*\s+(?:bulgu|sonuç|yanıt|cevap|çıktı|görüş|öneri|rapor|değerlendirme|çalışma)\p{L}*|(?:all|each|other|previous|fellow)\s+(?:agents?|experts?|specialists?)(?:[\u0027’]s?)?\s+(?:findings|outputs|answers|responses|recommendations|reports|assessments)|(?:uzman|ajan)\p{L}*\s+arasında\s+koordinasyon/iu.test(task)) {
  throw new Error('Uzman görevi ortak sorudan ve verilen kanıttan bağımsız olarak yapılabilmeli.');
}

if (!question) {
  throw new Error(
    'Worker input error: question must be a non-empty string.'
  );
}

if (!model) {
  throw new Error(
    'Worker input error: openaiModel or model must be a non-empty string.'
  );
}

if (!role) {
  throw new Error(
    'Worker input error: role must be a non-empty string.'
  );
}

if (!task) {
  throw new Error(
    'Worker input error: task must be a non-empty string.'
  );
}

if (
  !Number.isInteger(input.agentId) ||
  input.agentId < 1 ||
  input.agentId > 10
) {
  throw new Error(
    'Worker input error: agentId must be an integer from 1 to 10.'
  );
}

const allowedComplexities = new Set([
  'low',
  'medium',
  'high',
]);

const complexity =
  typeof input.complexity === 'string' &&
  allowedComplexities.has(input.complexity.trim().toLowerCase())
    ? input.complexity.trim().toLowerCase()
    : 'low';

return [
  {
    json: {
      question,
      model,
      openaiModel: model,

      questionType:
        typeof input.questionType === 'string' &&
        input.questionType.trim()
          ? input.questionType.trim()
          : 'genel',

      complexity,

      agentCount:
        Number.isInteger(input.agentCount) &&
        input.agentCount >= 1 &&
        input.agentCount <= 10
          ? input.agentCount
          : 1,

      agentId: input.agentId,
      role,
      task,
    },
  },
];

