const response = $input.first().json;
const source = $('Validate Worker Input').first().json;

if (response.status === 'incomplete') {
  throw new Error('Worker yanıtı tamamlanmadı: ' + (response.incomplete_details?.reason ?? 'bilinmeyen neden'));
}

// OpenAI Responses API içinden metin çıktısını bul.
const rawAnswer = response?.output
  ?.flatMap((item) =>
    Array.isArray(item?.content) ? item.content : []
  )
  ?.find((item) => item?.type === 'output_text')
  ?.text;

if (typeof rawAnswer !== 'string' || !rawAnswer.trim()) {
  throw new Error(
    'Worker yanıt hatası: ' +
    source.agentId +
    ' numaralı Worker OpenAI output_text döndürmedi.'
  );
}

if (source.attachment) {
  return [{ json: { evidence: rawAnswer.trim().slice(0, 12000) } }];
}

const text = rawAnswer.trim();
const words = [...text.matchAll(/\S+/g)];
const wordLimit = 220;
const needsShortening = words.length > wordLimit || /(?:…|\.{3})$/.test(text);
let answer = text;
if (needsShortening) {
  const end = words.length > wordLimit ? words[wordLimit].index : text.length;
  const complete = [...new Intl.Segmenter('tr', { granularity: 'sentence' }).segment(text)]
    .filter(({ segment, index }) => index + segment.trimEnd().length <= end
      && /[.!?]$/.test(segment.trimEnd()) && !/\.{3}$/.test(segment.trimEnd()))
    .at(-1);
  answer = complete
    ? text.slice(0, complete.index + complete.segment.trimEnd().length)
    : 'Uzman bu görev için sınır içinde tamamlanmış bir bulgu sunamadı.';
}

const wordCount = answer
  .split(/\s+/)
  .filter(Boolean)
  .length;

const containsMarkdownTable =
  /^\s*\|?.*\|.*$/m.test(answer) &&
  /^\s*\|?\s*:?-{3,}:?(?:\s*\|\s*:?-{3,}:?)+/m.test(answer);

return [
  {
    json: {
      question: source.question,
      model: source.model ?? 'gpt-5-mini',
      questionType: source.questionType,
      complexity: source.complexity,
      agentCount: source.agentCount,
      agentId: source.agentId,
      role: source.role,
      task: source.task,
      answer,
      wordCount,
      containsMarkdownTable,
    },
  },
];
